contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Owner (this contract) calls sendMoney once. Require we have enough funds in C to cover value.
    function run(address target, uint value, bytes calldata data) public payable {
        require(address(c).balance >= value, "c has insufficient balance");

        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;

        bool reverted;
        c.sendMoney(target, value, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBal = address(c).balance;

        // General rule: depositsCount unchanged; if call reverted then balance unchanged, else decreased by value
        assert(afterDeposits == beforeDeposits && (reverted ? afterBal == beforeBal : beforeBal == afterBal + value));
    }

    receive() external payable {}
}

